INSERT INTO movie_mood (movie_id,mood_id) SELECT m.movie_id,mo.mood_id FROM movies m CROSS JOIN moods mo WHERE (m.title IN ('3 Idiots','Queen','Chhichhore','The Hangover','Coco') AND mo.mood_name='😊 Happy') OR (m.title IN ('Taare Zameen Par','Tamasha','The Pursuit of Happyness','Kumbalangi Nights') AND mo.mood_name='😢 Sad') OR (m.title IN ('Yeh Jawaani Hai Deewani','Barfi!','Jab We Met','La La Land','Premam') AND mo.mood_name='❤️ Romantic') OR (m.title IN ('Andhadhun','Inception','The Dark Knight','RRR','Vikram') AND mo.mood_name='🔥 Excited') OR (m.title IN ('Zindagi Na Milegi Dobara','Coco','Spirited Away','Kumbalangi Nights') AND mo.mood_name='😌 Relaxed') OR (m.title IN ('Dangal','Swades','12th Fail','The Pursuit of Happyness') AND mo.mood_name='💪 Motivational') OR (m.title IN ('Tumbbad','Drishyam','Kahaani','Parasite','Vikram') AND mo.mood_name='😱 Thrilled') OR (m.title IN ('Interstellar','Inception','Parasite','Tamasha','Kantara') AND mo.mood_name='🧠 Thoughtful') ON CONFLICT DO NOTHING